export const CRAYS_QUARANTINED_MEDIA = CRAYS_PUBLIC_MEDIA_REGISTRY.filter(
  (asset) => asset.status.startsWith("quarantine-"),
);

export function getCraysMediaById(assetId: string) {
  return CRAYS_PUBLIC_MEDIA_REGISTRY.find((asset) => asset.assetId === assetId);
}

